export function setStandardView(cam: ViewCamera, view: StandardView): ViewCamera {
  let yaw = 0;
  let pitch = 0;

  switch (view) {
    case "front":
      yaw = 0;
      pitch = 0;
      break;
    case "back":
      yaw = Math.PI;
      pitch = 0;
      break;
    case "right":
      yaw = Math.PI / 2;
      pitch = 0;
      break;
    case "left":
      yaw = -Math.PI / 2;
      pitch = 0;
      break;
    case "top":
      yaw = 0;
      pitch = PITCH_LIMIT;
      break;
    case "bottom":
      yaw = 0;
      pitch = -PITCH_LIMIT;
      break;
  }

  return Object.freeze({
    ...cam,
    yaw,
    pitch,
  });

